__register('/utils/store.js', function (require, module, exports) {
// 收藏与浏览足迹（本地存储；随数据种子走，后端接入后可替换）
const KEY_FAV = 'shige_favorites';
const KEY_FOOT = 'shige_footprints';
const FOOT_MAX = 20;

function load(key) {
  try {
    return wx.getStorageSync(key) || [];
  } catch (e) {
    return [];
  }
}

function save(key, list) {
  try {
    wx.setStorageSync(key, list);
  } catch (e) { /* 存储异常时静默 */ }
}

function listFavorites() {
  return load(KEY_FAV);
}

function isFavorite(type, id) {
  return listFavorites().some((x) => x.type === type && x.id === id);
}

// 返回切换后的状态：true=已收藏，false=已取消
function toggleFavorite(type, id) {
  const list = listFavorites();
  const idx = list.findIndex((x) => x.type === type && x.id === id);
  if (idx >= 0) {
    list.splice(idx, 1);
    save(KEY_FAV, list);
    return false;
  }
  list.unshift({ type, id, ts: Date.now() });
  save(KEY_FAV, list);
  return true;
}

function addFootprint(type, id) {
  let list = load(KEY_FOOT).filter((x) => !(x.type === type && x.id === id));
  list.unshift({ type, id, ts: Date.now() });
  list = list.slice(0, FOOT_MAX);
  save(KEY_FOOT, list);
}

function listFootprints() {
  return load(KEY_FOOT);
}

function clearFavorites() {
  save(KEY_FAV, []);
}

function clearFootprints() {
  save(KEY_FOOT, []);
}

// switchTab 不带查询参数：跨 tab 的 mode 通过存储交接（时间轴分段用）
const KEY_TAB_PARAMS = 'shige_tab_params';

// 阅读字号：s 小 / m 标准 / l 大 / xl 特大（默认标准）
const KEY_FONT = 'shige_font_key';
const FONT_KEYS = ['s', 'm', 'l', 'xl'];

function getFontKey() {
  try {
    const v = wx.getStorageSync(KEY_FONT);
    return FONT_KEYS.indexOf(v) >= 0 ? v : 'm';
  } catch (e) {
    return 'm';
  }
}

function setFontKey(key) {
  const v = FONT_KEYS.indexOf(key) >= 0 ? key : 'm';
  save(KEY_FONT, v);
  return v;
}

function setPendingTimelineMode(mode) {
  save(KEY_TAB_PARAMS, { timelineMode: mode || 'ancient' });
}

function popPendingTimelineMode() {
  const cur = load('shige_tab_params');
  if (!cur || !cur.timelineMode) return '';
  try {
    wx.removeStorageSync(KEY_TAB_PARAMS);
  } catch (e) { /* 静默 */ }
  return cur.timelineMode;
}

module.exports = {
  listFavorites,
  isFavorite,
  toggleFavorite,
  addFootprint,
  listFootprints,
  clearFavorites,
  clearFootprints,
  setPendingTimelineMode,
  popPendingTimelineMode,
  getFontKey,
  setFontKey
};

});
__register('/utils/historyData.js', function (require, module, exports) {
// 数据中枢：所有页面统一从这里读历史数据
// - 初始返回打包内的本地种子 require('../data/history.js')（离线零依赖）
// - onShow 时页面调用 refresh()：jsDelivr 拉到新 JSON 且校验通过 → 热替换，
//   并通知订阅回调重建页面数据（内容更新不用发版）
// - 校验不通过/网络失败 → 保持 current 不变，UI 零影响
// - 09B 后 NestJS 上线时，仅需替换 remote.js 的 URL 与载荷解析

const seed = require('../data/history.js');
const remote = require('./remote.js');

let current = seed;
const subs = [];

function valid(data) {
  return !!(
    data &&
    data === Object(data) &&
    Array.isArray(data.events) &&
    data.events.length > 0 &&
    Array.isArray(data.persons) &&
    Array.isArray(data.periods) &&
    data.periods.length > 0 &&
    Array.isArray(data.topics) &&
    Array.isArray(data.daily) &&
    data.dailyFallback &&
    data.dailyFallback.eventId
  );
}

function get() {
  return current;
}

// 订阅数据热替换；若当前已是远端数据，注册即同步一次
function subscribe(fn) {
  if (typeof fn !== 'function') return;
  subs.push(fn);
  if (current !== seed) fn(current);
}

function apply(data) {
  if (data === current || !valid(data)) return false;
  current = data;
  subs.slice().forEach((fn) => {
    try {
      fn(current);
    } catch (e) {
      // 单个订阅方异常不阻断其他页面
    }
  });
  return true;
}

function sameData(a, b) {
  try {
    return JSON.stringify(a) === JSON.stringify(b);
  } catch (e) {
    return false;
  }
}

// cb(changed:boolean, err:Error|null)
// opts.fresh：用户主动「检查更新」——先 purge jsDelivr 缓存，再绕过本地缓存强制拉取
function refresh(cb, opts) {
  const fresh = !!(opts && opts.fresh);

  const proceed = (purgeErr) => {
    if (purgeErr) {
      if (typeof cb === 'function') cb(false, purgeErr);
      return;
    }
    remote.fetchRemoteHistory((err, data) => {
      if (err || !data) {
        if (typeof cb === 'function') cb(false, err);
        return;
      }
      if (sameData(data, current)) {
        if (typeof cb === 'function') cb(false, null);
        return;
      }
      if (typeof cb === 'function') cb(apply(data), null);
    }, { fresh });
  };

  if (fresh) remote.purgeRemoteCache(proceed);
  else proceed(null);
}

module.exports = {
  get,
  subscribe,
  refresh,
  valid
};

});
__register('/utils/remote.js', function (require, module, exports) {
// 远端数据源：jsDelivr CDN 直出仓库里的 data/history.json（真正接口化的最小形态）
// - 仓库更新 → CDN 同步（最长缓存 12 小时）→ 小程序内容更新，无需发版
// - 上线前需把 https://cdn.jsdelivr.net 加入小程序后台 request 合法域名
// - 本地按 24h 缓存最近一次成功结果；无网络/坏数据一律回调 err，
//   由 historyData 回退打包内的本地种子，页面永远有数据可渲染。

const REMOTE_URL =
  'https://cdn.jsdelivr.net/gh/webzol/history@main/miniprogram/data/history.json';
const PURGE_URL =
  'https://purge.jsdelivr.net/gh/webzol/history@main/miniprogram/data/history.json';
const CACHE_KEY = 'shige_history_remote';
const CACHE_TTL = 24 * 60 * 60 * 1000;

function readCache() {
  const raw = wx.getStorageSync(CACHE_KEY);
  if (!raw || !raw.data) return null;
  if (Date.now() - raw.at > CACHE_TTL) return null;
  return raw.data;
}

function writeCache(data) {
  try {
    wx.setStorageSync(CACHE_KEY, { at: Date.now(), data });
  } catch (e) {
    // 存储失败不影响当次使用
  }
}

// 请求 jsDelivr 清其 CDN 缓存（官方 purge 端点），让「检查更新」即时拉到新内容
function purgeRemoteCache(cb) {
  if (typeof wx.request !== 'function') {
    if (typeof cb === 'function') cb(new Error('request unavailable'));
    return;
  }
  wx.request({
    url: PURGE_URL,
    method: 'GET',
    timeout: 10000,
    success: () => {
      if (typeof cb === 'function') cb(null);
    },
    fail: () => {
      if (typeof cb === 'function') cb(new Error('purge fail'));
    }
  });
}

function fetchRemoteHistory(cb, opts) {
  const fresh = !!(opts && opts.fresh); // true = 绕过本地缓存强制拉取
  const cached = fresh ? null : readCache();
  if (cached) {
    if (typeof cb === 'function') cb(null, cached);
    return;
  }
  if (typeof wx.request !== 'function') {
    if (typeof cb === 'function') cb(new Error('request unavailable'));
    return;
  }
  wx.request({
    url: REMOTE_URL,
    method: 'GET',
    timeout: 10000,
    success: (res) => {
      const data = res && res.data;
      if (!data || !Array.isArray(data.events)) {
        if (typeof cb === 'function') cb(new Error('bad payload'));
        return;
      }
      writeCache(data);
      if (typeof cb === 'function') cb(null, data);
    },
    fail: () => {
      if (typeof cb === 'function') cb(new Error('request fail'));
    }
  });
}

module.exports = {
  REMOTE_URL,
  PURGE_URL,
  purgeRemoteCache,
  fetchRemoteHistory
};

});
__register('/utils/api.js', function (require, module, exports) {
// 在线数据源封装（首个真实接口）
// 数据源：60s API「历史上的今天」（开源免费、无需 Key）
//   原始结构 { code, message, data: { date, month, day, items: [{ title, year, description, event_type, link }] } }
//   上游同步自百度百科；开源仓库 https://github.com/vikiboss/60s
// 注意：
//   1) 开发者工具需勾选「不校验合法域名」；正式上线需把 https://60s.viki.moe
//      加入小程序后台 request 合法域名。
//   2) 上游限流较严，这里按「天」缓存最近一次成功结果（storage，TTL 6 小时）。
//   3) 任何失败（无网络/无 request 能力/空数据）都不抛错，仅回调 err，页面自行回退本地数据。

const SOURCE = 'https://60s.viki.moe/v2/today_in_history';
const CACHE_PREFIX = 'shige_tih_';
const CACHE_TTL = 6 * 60 * 60 * 1000; // 6h（成功结果）
const FAIL_TTL = 30 * 60 * 1000; // 30min（失败冷却：429/断网后一段时间内不再发请求）

function dateKey(date) {
  const d = date || new Date();
  return `${d.getMonth() + 1}-${d.getDate()}`;
}

// 归一化：剔除脏项 → 字段统一 → 按年份升序
function normalizeToday(payload) {
  const data = payload && payload.data;
  if (!payload || payload.code !== 200 || !data || !Array.isArray(data.items)) return [];
  return data.items
    .filter((item) => item && item.title && item.year)
    .map((item) => ({
      year: Number(String(item.year).replace(/\D/g, '')) || 0,
      yearText: String(item.year),
      title: String(item.title).replace(/\[.*?\]/g, ''),
      desc: item.description || '',
      type: item.event_type === 'birth' ? '出生' : item.event_type === 'death' ? '逝世' : '事件',
      link: item.link || ''
    }))
    .filter((item) => item.year > 0)
    .sort((a, b) => a.year - b.year);
}

// 读缓存：命中成功数据返回 { items }；处于失败冷却期返回 { cooldown: true }；否则 null
function readCache(day) {
  const raw = wx.getStorageSync(CACHE_PREFIX + day);
  if (!raw || raw.day !== day) return null;
  const age = Date.now() - raw.at;
  if (raw.fail) return age < FAIL_TTL ? { cooldown: true } : null;
  if (age > CACHE_TTL) return null;
  return Array.isArray(raw.items) && raw.items.length ? { items: raw.items } : null;
}

function writeCache(day, items) {
  try {
    wx.setStorageSync(CACHE_PREFIX + day, { day, at: Date.now(), items });
  } catch (e) {
    // 存储失败不影响本次展示
  }
}

function writeFail(day) {
  try {
    wx.setStorageSync(CACHE_PREFIX + day, { day, at: Date.now(), fail: true });
  } catch (e) {
    // 存储失败不影响本次展示
  }
}

function fetchTodayInHistory(cb) {
  const day = dateKey();
  const cached = readCache(day);
  if (cached) {
    if (typeof cb === 'function') {
      if (cached.cooldown) cb(new Error('cooldown')); // 冷却期：不打网络，页面自行隐藏板块
      else cb(null, cached.items);
    }
    return;
  }
  if (typeof wx.request !== 'function') {
    if (typeof cb === 'function') cb(new Error('request unavailable'));
    return;
  }
  wx.request({
    url: SOURCE,
    method: 'GET',
    timeout: 10000,
    success: (res) => {
      const items = normalizeToday(res && res.data);
      if (!items.length) {
        // 非 200 / 空数据（含 429 限流）：写失败冷却，板块自动隐藏
        writeFail(day);
        if (typeof cb === 'function') cb(new Error('empty payload'));
        return;
      }
      writeCache(day, items);
      if (typeof cb === 'function') cb(null, items);
    },
    fail: () => {
      writeFail(day);
      if (typeof cb === 'function') cb(new Error('request fail'));
    }
  });
}

module.exports = {
  SOURCE,
  dateKey,
  normalizeToday,
  fetchTodayInHistory
};

});
