__register('/pages/profile/profile.js', function (require, module, exports) {
const hd = require('../../utils/historyData.js');
const store = require('../../utils/store.js');
const font = require('../../utils/font.js');
const { resolveEntry, fmtWhen } = require('../../utils/entries.js');

Page('project://pages/profile/profile.js', {
  data: {
    stats: [
      { key: 'periods', label: '朝代', value: 0 },
      { key: 'events', label: '史事', value: 0 },
      { key: 'persons', label: '人物', value: 0 },
      { key: 'topics', label: '专题', value: 0 }
    ],
    favs: [],
    favsShow: [],
    favCount: 0,
    favHasMore: false,
    foots: [],
    footsShow: [],
    footCount: 0,
    footHasMore: false,
    info: { open: false, title: '', paragraphs: [] },
    updating: false,
    fontOptions: font.OPTIONS,
    fontKey: 'm',
    fontClass: 'm'
  },

  onLoad() {
    this.doStats();
  },

  onShow() {
    this.setTab();
    this.doStats();
    font.apply(this);
    this.setData({ fontKey: store.getFontKey() });
    hd.refresh((changed) => {
      if (changed) this.doStats();
    });
    const favs = store
      .listFavorites()
      .map((x, i) => resolveEntry(x, i))
      .filter(Boolean);
    const foots = store
      .listFootprints()
      .map((x, i) => {
        const entry = resolveEntry(x, i);
        return entry ? { ...entry, when: fmtWhen(x.ts) } : null;
      })
      .filter(Boolean);
    this.setData({
      favs,
      favsShow: favs.slice(0, 3),
      favCount: favs.length,
      favHasMore: favs.length > 3,
      foots,
      footsShow: foots.slice(0, 3),
      footCount: foots.length,
      footHasMore: foots.length > 3
    });
  },

  doStats() {
    const history = hd.get();
    this.setData({
      stats: [
        { key: 'periods', label: '朝代', value: history.periods.length },
        { key: 'events', label: '史事', value: history.events.length },
        { key: 'persons', label: '人物', value: history.persons.length },
        { key: 'topics', label: '专题', value: history.topics.length }
      ]
    });
  },

  setTab() {
    if (typeof this.getTabBar === 'function' && this.getTabBar()) {
      this.getTabBar().setData({ active: 'profile' });
    }
  },

  onSearch() {
    wx.navigateTo({ url: '/pages/search/search' });
  },

  onAllFoots() {
    wx.navigateTo({ url: '/pages/footprints/footprints' });
  },

  onAllFavs() {
    wx.navigateTo({ url: '/pages/favorites/favorites' });
  },

  onFontPick(e) {
    const key = e.currentTarget.dataset.key;
    const saved = store.setFontKey(key);
    this.setData({ fontKey: saved, fontClass: saved });
    const opt = font.OPTIONS.find((x) => x.key === saved);
    wx.showToast({ title: `字号：${opt ? opt.label : '标准'}`, icon: 'none' });
  },

  // 检查内容更新：purge jsDelivr 缓存 → 绕过本地缓存强制拉取
  onCheckUpdate() {
    if (this.data.updating) return;
    this.setData({ updating: true });
    wx.showLoading({ title: '检查更新', mask: true });
    hd.refresh((changed, err) => {
      this.setData({ updating: false });
      wx.hideLoading();
      if (err) {
        wx.showToast({ title: '暂无网络，稍后再试', icon: 'none' });
        return;
      }
      if (changed) {
        const meta = hd.get().meta || {};
        this.onShow(); // 重算统计与收藏/足迹解析
        wx.showToast({
          title: meta.builtAt ? `已更新 · ${meta.builtAt}` : '已更新至最新内容',
          icon: 'none',
          duration: 2600
        });
        return;
      }
      wx.showToast({ title: '内容已是最新', icon: 'none' });
    }, { fresh: true });
  },

  closeInfo() {
    this.setData({ 'info.open': false });
  },

  noop() {},

  onEntry(e) {
    const { type, id } = e.currentTarget.dataset;
    const url = type === 'person' ? `/pages/person/person?id=${id}` : `/pages/event/event?id=${id}`;
    const exist = hd.get()[type === 'person' ? 'persons' : 'events'].find((item) => item.id === id);
    if (!exist) return;
    wx.navigateTo({ url });
  },

  onFavLongPress(e) {
    const { type, id } = e.currentTarget.dataset;
    if (!store.isFavorite(type, id)) return;
    wx.showModal({
      title: '移出收藏',
      content: '确定将这条内容移出收藏？',
      confirmText: '移出',
      success: (res) => {
        if (!res.confirm) return;
        store.toggleFavorite(type, id);
        this.onShow();
        wx.showToast({ title: '已移出收藏', icon: 'none' });
      }
    });
  },

  onDataNote() {
    this.setData({
      info: {
        open: true,
        title: '数据与史料说明',
        paragraphs: [
          '当前内容为本地真实史料种子：',
          `朝代 ${this.data.stats[0].value} 条、史事 ${this.data.stats[1].value} 条、人物 ${this.data.stats[2].value} 条、专题 ${this.data.stats[3].value} 条。`,
          '每条均附史料出处索引；正式发布前会逐条完成历史审校。'
        ]
      }
    });
  },

  onAssetNote() {
    this.setData({
      info: {
        open: true,
        title: '素材与授权说明',
        paragraphs: [
          '插画与文物图片来自公开网络搜索与参考图裁切，仅用于原型演示；正式上线前将替换为有授权的来源。',
          '明细见工程 assets/paintings/SOURCES.md。'
        ]
      }
    });
  },

  onAbout() {
    this.setData({
      info: {
        open: true,
        title: '史页',
        paragraphs: ['一页一页读历史。古代史与近现代史并列，史料可追溯。']
      }
    });
  },

  onAboutBanner() {
    this.setData({
      info: {
        open: true,
        title: '千古长卷',
        paragraphs: ['王希孟《千里江山图》卷（局部），现藏故宫博物院。十八岁完成此卷，青绿千年不褪。']
      }
    });
  },

  onClearCache() {
    wx.showModal({
      title: '清除缓存',
      content: '只清空本地临时缓存；收藏与浏览足迹会一并清除。',
      confirmText: '清除',
      success: (res) => {
        if (!res.confirm) return;
        wx.clearStorageSync();
        this.onShow();
        wx.showToast({ title: '已清除', icon: 'success' });
      }
    });
  }
});

});
__register('/pages/profile/profile.wxml', function (require, module, exports) { module.exports = "<view class=\"page fs-{{fontClass}}\">\r\n  <image class=\"paper-bg\" src=\"/assets/paper-bg.jpg\" mode=\"aspectFill\"></image>\r\n  <view class=\"screen\">\r\n    <view class=\"topbar\">\r\n      <text class=\"brand\">我的</text>\r\n    </view>\r\n\r\n    <view class=\"head-card\">\r\n      <view class=\"avatar-wrap\">\r\n        <image class=\"avatar\" src=\"/assets/avatar-scholar.png\" mode=\"aspectFill\"></image>\r\n      </view>\r\n      <view class=\"head-info\">\r\n        <text class=\"nick\">史页客</text>\r\n        <text class=\"tagline\">以千年为卷轴，读万古事</text>\r\n      </view>\r\n      <image class=\"head-seal\" src=\"/assets/seal.png\" mode=\"aspectFit\"></image>\r\n    </view>\r\n\r\n    <view class=\"stats-card\">\r\n      <view class=\"stat\" wx:for=\"{{stats}}\" wx:key=\"key\">\r\n        <text class=\"stat-num\">{{item.value}}</text>\r\n        <text class=\"stat-label\">{{item.label}}</text>\r\n      </view>\r\n    </view>\r\n\r\n    <view class=\"pref-card\">\r\n      <view class=\"pref-head\">\r\n        <text class=\"pref-title\">阅读设置</text>\r\n        <text class=\"pref-note\">全站文字</text>\r\n      </view>\r\n      <view class=\"seg\">\r\n        <view\r\n          wx:for=\"{{fontOptions}}\"\r\n          wx:key=\"key\"\r\n          class=\"seg-item {{fontKey === item.key ? 'on' : ''}}\"\r\n          data-key=\"{{item.key}}\"\r\n          bindtap=\"onFontPick\"\r\n        >\r\n          <text>{{item.label}}</text>\r\n        </view>\r\n      </view>\r\n      <text class=\"pref-preview\">一页一页，读千年史事。</text>\r\n    </view>\r\n\r\n    <view class=\"plate-card\" bindtap=\"onAboutBanner\">\r\n      <view class=\"plate-frame\">\r\n        <image class=\"plate-img\" src=\"/assets/paintings/landscape.jpg\" mode=\"aspectFill\"></image>\r\n      </view>\r\n      <view class=\"plate-cap\">\r\n        <text class=\"plate-title\">千古长卷</text>\r\n        <text class=\"plate-sub\">王希孟《千里江山图》卷 · 故宫博物院藏</text>\r\n      </view>\r\n    </view>\r\n\r\n    <view class=\"list-card hint-card\" wx:if=\"{{!favs.length}}\">\r\n      <text class=\"hint-text\">还没有收藏。在人物、史事详情页点「收藏」，就会出现在这里。</text>\r\n    </view>\r\n    <view class=\"list-card\" wx:if=\"{{favs.length}}\">\r\n      <view class=\"list-head\">\r\n        <text class=\"list-title\">我的收藏</text>\r\n        <text class=\"list-count\">{{favCount}} 条</text>\r\n      </view>\r\n      <view\r\n        class=\"list-row\"\r\n        wx:for=\"{{favsShow}}\"\r\n        wx:key=\"id\"\r\n        data-type=\"{{item.type}}\"\r\n        data-id=\"{{item.id}}\"\r\n        bindtap=\"onEntry\"\r\n        bindlongpress=\"onFavLongPress\"\r\n      >\r\n        <image class=\"row-thumb {{item.modern ? 'row-thumb-modern' : ''}}\" src=\"{{item.img}}\" mode=\"aspectFill\"></image>\r\n        <view class=\"row-main\">\r\n          <text class=\"row-title\">{{item.title}}</text>\r\n          <text class=\"row-sub {{item.modern ? 'sub-modern' : ''}}\">{{item.sub}}</text>\r\n        </view>\r\n        <text class=\"row-arrow\">›</text>\r\n      </view>\r\n      <view class=\"list-fold\" wx:if=\"{{favHasMore}}\" bindtap=\"onAllFavs\">\r\n        <text class=\"fold-text\">查看全部收藏</text>\r\n        <text class=\"fold-count\">{{favCount}} 条</text>\r\n        <text class=\"fold-arrow\">›</text>\r\n      </view>\r\n    </view>\r\n\r\n    <view class=\"list-card hint-card\" wx:if=\"{{!foots.length}}\">\r\n      <text class=\"hint-text\">还没有足迹。浏览人物、史事、朝代详情页后会留下足迹。</text>\r\n    </view>\r\n    <view class=\"list-card\" wx:if=\"{{foots.length}}\">\r\n      <view class=\"list-head\">\r\n        <text class=\"list-title\">浏览足迹</text>\r\n        <text class=\"list-count\">{{footCount}} 条</text>\r\n      </view>\r\n      <view\r\n        class=\"list-row\"\r\n        wx:for=\"{{footsShow}}\"\r\n        wx:key=\"id\"\r\n        data-type=\"{{item.type}}\"\r\n        data-id=\"{{item.id}}\"\r\n        bindtap=\"onEntry\"\r\n      >\r\n        <image class=\"row-thumb {{item.modern ? 'row-thumb-modern' : ''}}\" src=\"{{item.img}}\" mode=\"aspectFill\"></image>\r\n        <view class=\"row-main\">\r\n          <text class=\"row-title\">{{item.title}}</text>\r\n          <text class=\"row-sub {{item.modern ? 'sub-modern' : ''}}\">{{item.sub}}</text>\r\n        </view>\r\n        <text class=\"row-when\">{{item.when}}</text>\r\n      </view>\r\n      <view class=\"list-fold\" wx:if=\"{{footHasMore}}\" bindtap=\"onAllFoots\">\r\n        <text class=\"fold-text\">查看全部足迹</text>\r\n        <text class=\"fold-count\">{{footCount}} 条</text>\r\n        <text class=\"fold-arrow\">›</text>\r\n      </view>\r\n    </view>\r\n\r\n    <view class=\"menu-card\">\r\n      <view class=\"menu-row\" bindtap=\"onSearch\">\r\n        <text class=\"menu-label\">搜索史事 · 人物</text>\r\n        <text class=\"menu-arrow\">›</text>\r\n      </view>\r\n      <view class=\"menu-row\" bindtap=\"onCheckUpdate\">\r\n        <text class=\"menu-label\">检查内容更新</text>\r\n        <text class=\"menu-arrow\">›</text>\r\n      </view>\r\n      <view class=\"menu-row\" bindtap=\"onDataNote\">\r\n        <text class=\"menu-label\">数据与史料说明</text>\r\n        <text class=\"menu-arrow\">›</text>\r\n      </view>\r\n      <view class=\"menu-row\" bindtap=\"onAssetNote\">\r\n        <text class=\"menu-label\">素材与授权说明</text>\r\n        <text class=\"menu-arrow\">›</text>\r\n      </view>\r\n      <view class=\"menu-row\" bindtap=\"onAbout\">\r\n        <text class=\"menu-label\">关于史页</text>\r\n        <text class=\"menu-arrow\">›</text>\r\n      </view>\r\n      <view class=\"menu-row last\" bindtap=\"onClearCache\">\r\n        <text class=\"menu-label\">清除缓存</text>\r\n        <text class=\"menu-arrow\">›</text>\r\n      </view>\r\n    </view>\r\n  </view>\r\n\r\n  <view class=\"sheet-layer\" wx:if=\"{{info.open}}\">\r\n    <view class=\"sheet-mask\" bindtap=\"closeInfo\"></view>\r\n    <view class=\"info-panel\" catchtap=\"noop\">\r\n      <view class=\"sheet-grip\"></view>\r\n      <view class=\"sheet-head\">\r\n        <text class=\"sheet-title\">{{info.title}}</text>\r\n        <text class=\"sheet-close\" bindtap=\"closeInfo\">×</text>\r\n      </view>\r\n      <view class=\"info-body\">\r\n        <text class=\"info-para\" wx:for=\"{{info.paragraphs}}\" wx:key=\"*this\">{{item}}</text>\r\n      </view>\r\n      <view class=\"sheet-cancel\" bindtap=\"closeInfo\">知道了</view>\r\n    </view>\r\n  </view>\r\n\r\n</view>\r\n"; });
__register('/pages/profile/profile.wxss', function (require, module, exports) { module.exports = ".page {\n  position: relative;\n  min-height: 100vh;\n  overflow: hidden;\n  background: #F6F1EA;\n}\n\n.paper-bg {\n  position: fixed;\n  left: 0;\n  top: 0;\n  z-index: 0;\n  width: 100%;\n  height: 100%;\n  opacity: 0.96;\n}\n\n.screen {\n  position: relative;\n  z-index: 2;\n  padding: 0 46rpx 160rpx;\n}\n\n.topbar {\n  margin-top: 88rpx;\n  height: 124rpx;\n  display: flex;\n  align-items: center;\n}\n\n.brand {\n  font-family: \"Songti SC\", \"STSong\", \"SimSun\", serif;\n  font-size: calc(54rpx * var(--fs, 1));\n  font-weight: 400;\n  letter-spacing: 0.08em;\n  color: #1F1D19;\n}\n\n/* 用户头卡 */\n.head-card {\n  margin-top: 22rpx;\n  padding: 34rpx;\n  border-radius: 38rpx;\n  background: #FCFBF8;\n  box-shadow: 0 20rpx 46rpx rgba(90, 70, 50, 0.06);\n  display: flex;\n  align-items: center;\n  gap: 24rpx;\n}\n\n.avatar-wrap {\n  width: 112rpx;\n  height: 112rpx;\n  border-radius: 50%;\n  overflow: hidden;\n  background: #F3EFE6;\n  border: 4rpx solid #FFFDF8;\n  box-shadow: 0 8rpx 20rpx rgba(90, 70, 50, 0.12);\n}\n\n.avatar {\n  width: 100%;\n  height: 100%;\n  display: block;\n}\n\n.head-info {\n  flex: 1;\n  min-width: 0;\n}\n\n.nick {\n  display: block;\n  font-family: \"Songti SC\", \"STSong\", \"SimSun\", serif;\n  font-size: calc(36rpx * var(--fs, 1));\n  letter-spacing: 0.06em;\n  color: #1F1D19;\n}\n\n.tagline {\n  display: block;\n  margin-top: 10rpx;\n  font-size: calc(20rpx * var(--fs, 1));\n  letter-spacing: 0.03em;\n  color: #8C857A;\n}\n\n.head-seal {\n  width: 72rpx;\n  height: 72rpx;\n  flex: 0 0 72rpx;\n  display: block;\n  opacity: 0.92;\n  transform: rotate(2deg);\n}\n\n/* 数据统计 */\n.stats-card {\n  margin-top: 18rpx;\n  padding: 30rpx 20rpx;\n  border-radius: 34rpx;\n  background: #FCFBF8;\n  box-shadow: 0 16rpx 34rpx rgba(90, 70, 50, 0.045);\n  display: flex;\n}\n\n.stat {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 8rpx;\n}\n\n.stat-num {\n  font-family: \"Songti SC\", \"STSong\", \"SimSun\", serif;\n  font-size: calc(44rpx * var(--fs, 1));\n  line-height: 1;\n  color: #A9825E;\n}\n\n.stat-label {\n  font-size: calc(20rpx * var(--fs, 1));\n  letter-spacing: 0.05em;\n  color: #8C857A;\n}\n\n/* 阅读设置 */\n.pref-card {\n  margin-top: 18rpx;\n  padding: 26rpx 28rpx 24rpx;\n  border-radius: 34rpx;\n  background: #FCFBF8;\n  box-shadow: 0 16rpx 34rpx rgba(90, 70, 50, 0.045);\n}\n\n.pref-head {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n}\n\n.pref-title {\n  font-family: \"Songti SC\", \"STSong\", \"SimSun\", serif;\n  font-size: calc(27rpx * var(--fs, 1));\n  letter-spacing: 0.06em;\n  color: #1F1D19;\n}\n\n.pref-note {\n  font-size: calc(18rpx * var(--fs, 1));\n  letter-spacing: 0.03em;\n  color: #A39A8E;\n}\n\n.seg {\n  display: flex;\n  gap: 10rpx;\n  margin-top: 20rpx;\n}\n\n.seg-item {\n  flex: 1;\n  height: 64rpx;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 32rpx;\n  border: 1rpx solid rgba(70, 58, 45, 0.12);\n  background: #FBF9F6;\n  font-size: calc(22rpx * var(--fs, 1));\n  letter-spacing: 0.06em;\n  color: #5F5A52;\n}\n\n.seg-item.on {\n  border-color: rgba(169, 130, 94, 0.55);\n  background: rgba(169, 130, 94, 0.10);\n  color: #8E5E36;\n}\n\n.pref-preview {\n  display: block;\n  margin-top: 18rpx;\n  font-size: calc(22rpx * var(--fs, 1));\n  font-family: \"Songti SC\", \"STSong\", \"SimSun\", serif;\n  letter-spacing: 0.04em;\n  line-height: 1.7;\n  color: #3B3731;\n}\n\n/* 千古长卷：装裱画片（画心 + 底部题签） */\n.plate-card {\n  margin-top: 18rpx;\n  padding: 14rpx 14rpx 16rpx;\n  border-radius: 36rpx;\n  background: #FCFBF8;\n  box-shadow: 0 20rpx 46rpx rgba(90, 70, 50, 0.06);\n}\n\n.plate-frame {\n  height: 208rpx;\n  border-radius: 24rpx;\n  overflow: hidden;\n  background: #F3EFE6;\n  border: 1rpx solid rgba(70, 58, 45, 0.08);\n}\n\n.plate-img {\n  width: 100%;\n  height: 100%;\n  display: block;\n  filter: saturate(0.86) contrast(1.02) brightness(1.02);\n}\n\n.plate-cap {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 16rpx;\n  padding: 16rpx 10rpx 2rpx;\n}\n\n.plate-title {\n  font-family: \"Songti SC\", \"STSong\", \"SimSun\", serif;\n  font-size: calc(28rpx * var(--fs, 1));\n  letter-spacing: 0.08em;\n  color: #1F1D19;\n}\n\n.plate-sub {\n  font-size: calc(17rpx * var(--fs, 1));\n  letter-spacing: 0.03em;\n  line-height: 1.5;\n  color: #8C857A;\n  text-align: right;\n}\n\n/* 功能清单 */\n.menu-card {\n  margin-top: 22rpx;\n  border-radius: 34rpx;\n  background: #FCFBF8;\n  box-shadow: 0 16rpx 34rpx rgba(90, 70, 50, 0.045);\n  padding: 6rpx 28rpx;\n}\n\n.menu-row {\n  display: flex;\n  align-items: center;\n  height: 96rpx;\n  border-bottom: 1rpx solid rgba(70, 58, 45, 0.07);\n}\n\n.menu-row.last {\n  border-bottom: none;\n}\n\n.menu-label {\n  flex: 1;\n  font-size: calc(24rpx * var(--fs, 1));\n  letter-spacing: 0.04em;\n  color: #2C2924;\n}\n\n.menu-hint {\n  margin-right: 14rpx;\n  font-size: calc(18rpx * var(--fs, 1));\n  letter-spacing: 0.04em;\n  color: #A39A8E;\n}\n\n.menu-arrow {\n  font-family: \"Songti SC\", \"STSong\", \"SimSun\", serif;\n  font-size: 30rpx;\n  color: #A39A8E;\n}\n\n/* 收藏 / 足迹列表 */\n.list-card {\n  margin-top: 22rpx;\n  border-radius: 34rpx;\n  background: #FCFBF8;\n  box-shadow: 0 16rpx 34rpx rgba(90, 70, 50, 0.045);\n  padding: 26rpx 28rpx 12rpx;\n}\n\n.hint-card {\n  padding: 26rpx 28rpx;\n}\n\n.hint-text {\n  display: block;\n  font-size: calc(24rpx * var(--fs, 1));\n  line-height: calc(38rpx * var(--fs, 1));\n  color: #8C857A;\n}\n\n.list-head {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  padding: 0 4rpx 14rpx;\n}\n\n.list-title {\n  font-family: \"Songti SC\", \"STSong\", \"SimSun\", serif;\n  font-size: calc(27rpx * var(--fs, 1));\n  letter-spacing: 0.06em;\n  color: #1F1D19;\n}\n\n.list-count {\n  font-size: calc(18rpx * var(--fs, 1));\n  letter-spacing: 0.05em;\n  color: #A39A8E;\n}\n\n.list-row {\n  display: flex;\n  align-items: center;\n  gap: 20rpx;\n  padding: 20rpx 4rpx;\n  border-top: 1rpx solid rgba(70, 58, 45, 0.07);\n}\n\n.row-thumb {\n  flex: 0 0 72rpx;\n  width: 72rpx;\n  height: 72rpx;\n  display: block;\n  border-radius: 18rpx;\n  background: #F3EFE6;\n  border: 3rpx solid #FFFDF8;\n  box-shadow: 0 4rpx 10rpx rgba(90, 70, 50, 0.08);\n  filter: saturate(0.86) brightness(1.02);\n}\n\n.row-thumb.row-thumb-modern {\n  filter: saturate(0.7) brightness(1.03);\n}\n\n.row-main {\n  flex: 1;\n  min-width: 0;\n}\n\n.row-title {\n  display: block;\n  font-family: \"Songti SC\", \"STSong\", \"SimSun\", serif;\n  font-size: calc(24rpx * var(--fs, 1));\n  letter-spacing: 0.04em;\n  color: #1F1D19;\n}\n\n.row-sub {\n  display: block;\n  margin-top: 6rpx;\n  font-size: calc(18rpx * var(--fs, 1));\n  letter-spacing: 0.03em;\n  color: #8C857A;\n}\n\n.row-sub.sub-modern {\n  color: #7E9A9A;\n}\n\n.row-arrow {\n  font-family: \"Songti SC\", \"STSong\", \"SimSun\", serif;\n  font-size: 30rpx;\n  color: #A39A8E;\n}\n\n.row-when {\n  flex: 0 0 auto;\n  font-size: calc(17rpx * var(--fs, 1));\n  letter-spacing: 0.02em;\n  color: #A39A8E;\n}\n\n/* 足迹折叠：只展示前三条，查看更多进独立页 */\n.list-fold {\n  display: flex;\n  align-items: center;\n  gap: 10rpx;\n  padding: 22rpx 4rpx 12rpx;\n  border-top: 1rpx solid rgba(70, 58, 45, 0.07);\n}\n\n.fold-text {\n  flex: 1;\n  font-size: calc(20rpx * var(--fs, 1));\n  letter-spacing: 0.06em;\n  color: #8E5E36;\n}\n\n.fold-count {\n  font-size: calc(17rpx * var(--fs, 1));\n  letter-spacing: 0.03em;\n  color: #A39A8E;\n}\n\n.fold-arrow {\n  font-family: \"Songti SC\", \"STSong\", \"SimSun\", serif;\n  font-size: 30rpx;\n  line-height: 1;\n  color: #A9825E;\n}\n\n/* 信息弹层（与首页磁贴弹层同风格） */\n.sheet-layer {\n  position: fixed;\n  left: 0;\n  right: 0;\n  top: 0;\n  bottom: 0;\n  z-index: 120;\n}\n\n.sheet-mask {\n  position: absolute;\n  left: 0;\n  right: 0;\n  top: 0;\n  bottom: 0;\n  background: rgba(31, 29, 25, 0.3);\n  animation: sheetFade 0.18s ease both;\n}\n\n.info-panel {\n  position: absolute;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  max-height: 62vh;\n  padding: 16rpx 34rpx calc(30rpx + env(safe-area-inset-bottom));\n  background: #FCFBF8;\n  border-radius: 42rpx 42rpx 0 0;\n  box-shadow: 0 -24rpx 52rpx rgba(90, 70, 50, 0.16);\n  animation: sheetUp 0.24s cubic-bezier(0.2, 0.8, 0.3, 1) both;\n}\n\n.sheet-grip {\n  width: 66rpx;\n  height: 6rpx;\n  margin: 4rpx auto 14rpx;\n  border-radius: 3rpx;\n  background: #E6E0D4;\n}\n\n.sheet-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 6rpx 8rpx 16rpx;\n  border-bottom: 1rpx solid rgba(31, 29, 25, 0.06);\n}\n\n.sheet-title {\n  font-family: \"Songti SC\", \"STSong\", \"SimSun\", serif;\n  font-size: calc(33rpx * var(--fs, 1));\n  letter-spacing: 0.07em;\n  color: #1F1D19;\n}\n\n.sheet-close {\n  font-size: 40rpx;\n  line-height: 1;\n  padding: 6rpx 12rpx;\n  color: #8C857A;\n}\n\n.info-body {\n  max-height: 40vh;\n  overflow-y: auto;\n  padding: 10rpx 8rpx 6rpx;\n}\n\n.info-para {\n  display: block;\n  margin-bottom: 22rpx;\n  font-size: calc(24rpx * var(--fs, 1));\n  line-height: 1.8;\n  color: #3B3731;\n}\n\n.sheet-cancel {\n  margin-top: 18rpx;\n  height: 84rpx;\n  border-radius: 42rpx;\n  background: #EEF0F0;\n  font-size: calc(26rpx * var(--fs, 1));\n  letter-spacing: 0.08em;\n  color: #5F5A52;\n  text-align: center;\n  line-height: calc(84rpx * var(--fs, 1));\n}\n\n@keyframes sheetFade {\n  from { opacity: 0; }\n  to { opacity: 1; }\n}\n\n@keyframes sheetUp {\n  from { transform: translateY(42%); opacity: 0.4; }\n  to { transform: translateY(0); opacity: 1; }\n}\n\n"; });
__register('/pages/event/event.js', function (require, module, exports) {
const hd = require('../../utils/historyData.js');
const store = require('../../utils/store.js');
const font = require('../../utils/font.js');
const eraImage = require('../../utils/eraImages.js').eraImage;
const personThumb = require('../../utils/eraImages.js').personThumb;

Page('project://pages/event/event.js', {
  data: {
    event: null,
    seal: '',
    headImg: '',
    relatedPersons: [],
    collected: false,
    fontClass: 'm'
  },

  onLoad(options) {
    font.apply(this);
    this.curId = options.id;
    this.apply(true);
    hd.refresh((changed) => {
      if (changed) this.apply(false);
    });
  },

  onShow() {
    font.apply(this);
  },

  apply(redirectOnMiss) {
    const event = hd.get().events.find((item) => item.id === this.curId);
    if (!event) {
      if (!redirectOnMiss) return;
      wx.navigateBack({ fail: () => wx.redirectTo({ url: '/pages/home/home' }) });
      return;
    }

    // 反查人物列表：人物详情里登记过 relatedEvents 的人，即与该事件相关
    const relatedPersons = hd
      .get()
      .persons.filter((person) =>
        (person.relatedEvents || []).indexOf(event.id) >= 0
      )
      .map((person, index) => ({ ...person, img: personThumb(person.era, index) }));

    this.setData({
      event,
      headImg: eraImage(event.era),
      relatedPersons,
      seal: event.title.charAt(0),
      collected: store.isFavorite('event', event.id)
    });

    store.addFootprint('event', event.id);
  },

  toggleCollect() {
    if (!this.data.event) return;
    const on = store.toggleFavorite('event', this.data.event.id);
    this.setData({ collected: on });
    wx.showToast({ title: on ? '已收藏' : '已取消收藏', icon: 'none' });
  },

  goBack() {
    wx.navigateBack({
      fail: () => wx.redirectTo({ url: '/pages/home/home' })
    });
  },

  goPerson(e) {
    wx.navigateTo({
      url: `/pages/person/person?id=${e.currentTarget.dataset.id}`
    });
  },

  goTimeline() {
    store.setPendingTimelineMode(this.data.event.mode);
    wx.switchTab({ url: '/pages/timeline/timeline' });
  },

  onShareAppMessage() {
    const event = this.data.event;
    return {
      title: event ? `${event.title} · 史页` : '史页',
      path: event ? `/pages/event/event?id=${event.id}` : '/pages/home/home'
    };
  }
});

});
