__register('/pages/person/person.js', function (require, module, exports) {
const hd = require('../../utils/historyData.js');
const store = require('../../utils/store.js');
const font = require('../../utils/font.js');
const eraImage = require('../../utils/eraImages.js').eraImage;
const personThumb = require('../../utils/eraImages.js').personThumb;

// 近现代识别色为蓝灰；其余时代走古代赭石色
const MODERN_ERAS = ['晚清', '民国', '新中国', '近现代', '现代'];

Page('project://pages/person/person.js', {
  data: {
    person: null,
    accent: 'ancient',
    seal: '',
    headImg: '',
    related: [],
    collected: false,
    fontClass: 'm'
  },

  onLoad(options) {
    font.apply(this);
    this.curId = options.id;
    this.apply(true);
    hd.refresh((changed) => {
      if (changed) this.apply(false);
    });
  },

  onShow() {
    font.apply(this);
  },

  apply(redirectOnMiss) {
    const history = hd.get();
    const person = history.persons.find((item) => item.id === this.curId);
    if (!person) {
      if (!redirectOnMiss) return;
      wx.navigateBack({ fail: () => wx.redirectTo({ url: '/pages/home/home' }) });
      return;
    }

    const related = (person.relatedEvents || [])
      .map((id) => history.events.find((event) => event.id === id))
      .filter(Boolean)
      .map((event, index) => ({ ...event, img: personThumb(event.era, index) }));

    this.setData({
      person,
      related,
      headImg: eraImage(person.era),
      accent: MODERN_ERAS.indexOf(person.era) >= 0 ? 'modern' : 'ancient',
      seal: person.name.charAt(0),
      collected: store.isFavorite('person', person.id)
    });

    store.addFootprint('person', person.id);
  },

  toggleCollect() {
    if (!this.data.person) return;
    const on = store.toggleFavorite('person', this.data.person.id);
    this.setData({ collected: on });
    wx.showToast({ title: on ? '已收藏' : '已取消收藏', icon: 'none' });
  },

  goBack() {
    wx.navigateBack({
      fail: () => wx.redirectTo({ url: '/pages/home/home' })
    });
  },

  goEvent(e) {
    wx.navigateTo({
      url: `/pages/event/event?id=${e.currentTarget.dataset.id}`
    });
  },

  onShareAppMessage() {
    const person = this.data.person;
    return {
      title: person ? `${person.name} · 史页` : '史页',
      path: person ? `/pages/person/person?id=${person.id}` : '/pages/home/home'
    };
  }
});

});
__register('/pages/person/person.wxml', function (require, module, exports) { module.exports = "<view class=\"page fs-{{fontClass}}\">\r\n  <image class=\"paper-bg\" src=\"/assets/paper-bg.jpg\" mode=\"aspectFill\"></image>\r\n  <view class=\"screen\" wx:if=\"{{person}}\">\r\n    <view class=\"topbar\">\r\n      <view class=\"back\" bindtap=\"goBack\" hover-class=\"back-pressed\" hover-stay-time=\"80\">\r\n        <view class=\"back-icon\">\r\n          <view class=\"back-chevron\"></view>\r\n          <view class=\"back-shaft\"></view>\r\n        </view>\r\n        <view class=\"back-divider\"></view>\r\n        <text class=\"back-label\">返回</text>\r\n      </view>\r\n      <text class=\"top-title\">人物</text>\r\n      <text class=\"top-seal {{accent === 'modern' ? 'seal-modern' : ''}}\">{{seal}}</text>\r\n    </view>\r\n\r\n    <view class=\"head-card\">\r\n      <image class=\"p-bg\" wx:if=\"{{headImg}}\" src=\"{{headImg}}\" mode=\"aspectFill\"></image>\r\n      <view class=\"p-veil\"></view>\r\n      <view class=\"p-copy\">\r\n        <text class=\"p-name\">{{person.name}}</text>\r\n        <view class=\"p-meta\">\r\n          <text class=\"p-dates {{accent === 'modern' ? 'accent-modern' : ''}}\">{{person.dates}}</text>\r\n          <text class=\"p-dot\">·</text>\r\n          <text class=\"p-roles\">{{person.roles}}</text>\r\n        </view>\r\n        <view class=\"era-chip {{accent === 'modern' ? 'chip-modern' : ''}}\">\r\n          <text>{{person.era}}</text>\r\n        </view>\r\n        <view class=\"quote-block\" wx:if=\"{{person.quote}}\">\r\n          <text class=\"quote-mark\">“</text>\r\n          <text class=\"quote\">{{person.quote}}</text>\r\n          <text class=\"quote-src\">——{{person.quoteSource}}</text>\r\n        </view>\r\n      </view>\r\n    </view>\r\n\r\n    <view class=\"body-card\">\r\n      <view class=\"para\" wx:for=\"{{person.details}}\" wx:key=\"*this\">\r\n        <text>{{item}}</text>\r\n      </view>\r\n    </view>\r\n\r\n    <view class=\"section-head\" wx:if=\"{{related.length}}\">\r\n      <text class=\"section-title\">生平际会 · 相关史事</text>\r\n    </view>\r\n    <view class=\"rel-list\" wx:if=\"{{related.length}}\">\r\n      <view\r\n        wx:for=\"{{related}}\"\r\n        wx:key=\"id\"\r\n        class=\"rel-card\"\r\n        data-id=\"{{item.id}}\"\r\n        bindtap=\"goEvent\"\r\n      >\r\n        <text class=\"rel-year {{accent === 'modern' && item.mode === 'modern' ? 'accent-modern' : ''}}\">{{item.yearText}}</text>\r\n        <view class=\"rel-body\">\r\n          <text class=\"rel-title\">{{item.title}}</text>\r\n          <text class=\"rel-desc\">{{item.desc}}</text>\r\n        </view>\r\n        <image class=\"rel-thumb\" wx:if=\"{{item.img}}\" src=\"{{item.img}}\" mode=\"aspectFill\"></image>\r\n        <text class=\"rel-arrow\">›</text>\r\n      </view>\r\n    </view>\r\n\r\n    <view class=\"foot-actions\">\r\n      <view class=\"ghost-btn {{collected ? (accent === 'modern' ? 'on on-modern' : 'on') : ''}}\" bindtap=\"toggleCollect\">\r\n        <text>{{collected ? '✓ 已收藏此人物' : '收藏此人物'}}</text>\r\n      </view>\r\n    </view>\r\n\r\n    <view class=\"source-line\">史料 · {{person.source}}</view>\r\n  </view>\r\n</view>\r\n"; });
