__register('/pages/search/search.js', function (require, module, exports) {
const hd = require('../../utils/historyData.js');
const store = require('../../utils/store.js');
const font = require('../../utils/font.js');

const lower = (text) => (text || '').toLowerCase();

Page('project://pages/search/search.js', {
  data: {
    keyword: '',
    hot: ['孔子', '秦始皇', '赤壁之战', '岳飞', '张居正', '辛亥革命'],
    results: null,
    empty: false,
    fontClass: 'm'
  },

  onShow() {
    font.apply(this);
  },

  onInput(e) {
    const keyword = e.detail.value;
    this.setData({
      keyword,
      results: keyword.trim() ? this.data.results : null,
      empty: keyword.trim() ? this.data.empty : false
    });
  },

  onSearch() {
    const word = this.data.keyword.trim();
    if (!word) {
      this.setData({ results: null, empty: false });
      return;
    }
    const kw = lower(word);
    const hit = (fields) => fields.some((field) => lower(field).indexOf(kw) >= 0);
    const modern = (era) => (era || '').indexOf('近现') >= 0 || (era || '').indexOf('民国') >= 0;
    const history = hd.get();

    const persons = history.persons
      .filter((p) => hit([p.name, p.era, p.roles, p.summary, p.dates].concat(p.details || [])))
      .map((p) => ({
        id: p.id,
        title: p.name,
        sub: `${p.era} · ${p.roles}`,
        modern: modern(p.era)
      }));

    const events = history.events
      .filter((e) => hit([e.title, e.era, e.tags, e.desc, e.yearText].concat(e.details || [])))
      .map((e) => ({
        id: e.id,
        title: e.title,
        sub: `${e.yearText} · ${e.era}`,
        modern: e.mode === 'modern'
      }));

    const panels = []
      .concat(
        history.periods.map((p) => ({
          id: p.id,
          key: `period-${p.id}`,
          title: p.name,
          sub: `${p.start < 0 ? `公元前${-p.start}` : p.start}–${p.end < 0 ? `公元前${-p.end}` : p.end}`,
          mode: p.id === 'modern' ? 'modern' : 'ancient',
          modern: p.id === 'modern'
        })),
        history.topics.map((t) => ({
          id: t.id,
          key: `topic-${t.id}`,
          title: t.shortTitle || t.title,
          sub: t.kicker,
          mode: t.id === 'modern-china' ? 'modern' : 'ancient',
          modern: t.id === 'modern-china'
        }))
      )
      .filter((p) => hit([p.title, p.sub]));

    this.setData({
      results: { persons, events, panels },
      empty: !persons.length && !events.length && !panels.length
    });
  },

  onHotTap(e) {
    const word = e.currentTarget.dataset.word;
    this.setData({ keyword: word }, () => this.onSearch());
  },

  onRowTap(e) {
    const { type, id, mode } = e.currentTarget.dataset;
    if (type === 'person') {
      wx.navigateTo({ url: `/pages/person/person?id=${id}` });
    } else if (type === 'event') {
      wx.navigateTo({ url: `/pages/event/event?id=${id}` });
    } else {
      store.setPendingTimelineMode(mode || 'ancient');
      wx.switchTab({ url: '/pages/timeline/timeline' });
    }
  },

  goBack() {
    wx.navigateBack({ fail: () => wx.redirectTo({ url: '/pages/home/home' }) });
  }
});

});
__register('/pages/search/search.wxml', function (require, module, exports) { module.exports = "<view class=\"page fs-{{fontClass}}\">\r\n  <image class=\"paper-bg\" src=\"/assets/paper-bg.jpg\" mode=\"aspectFill\"></image>\r\n  <view class=\"screen\">\r\n\r\n    <view class=\"topbar\">\r\n      <view class=\"back\" bindtap=\"goBack\" hover-class=\"back-pressed\" hover-stay-time=\"80\">\r\n        <view class=\"back-icon\">\r\n          <view class=\"back-chevron\"></view>\r\n          <view class=\"back-shaft\"></view>\r\n        </view>\r\n        <view class=\"back-divider\"></view>\r\n        <text class=\"back-label\">返回</text>\r\n      </view>\r\n      <text class=\"top-title\">搜索</text>\r\n      <image class=\"top-seal\" src=\"/assets/seal.png\" mode=\"aspectFit\"></image>\r\n    </view>\r\n\r\n    <view class=\"search-card\">\r\n      <text class=\"search-icon\">⌕</text>\r\n      <input\r\n        class=\"search-input\"\r\n        value=\"{{keyword}}\"\r\n        placeholder=\"搜史事 · 人物 · 朝代\"\r\n        placeholder-class=\"ph\"\r\n        confirm-type=\"search\"\r\n        focus\r\n        bindinput=\"onInput\"\r\n        bindconfirm=\"onSearch\"\r\n      />\r\n      <text class=\"search-btn\" bindtap=\"onSearch\">搜索</text>\r\n    </view>\r\n\r\n    <block wx:if=\"{{!results}}\">\r\n      <view class=\"section-head\">\r\n        <text class=\"section-title\">热门检索</text>\r\n      </view>\r\n      <view class=\"hot-wrap\">\r\n        <text\r\n          wx:for=\"{{hot}}\"\r\n          wx:key=\"*this\"\r\n          class=\"hot-chip\"\r\n          data-word=\"{{item}}\"\r\n          bindtap=\"onHotTap\"\r\n        >{{item}}</text>\r\n      </view>\r\n    </block>\r\n\r\n    <block wx:else>\r\n      <block wx:if=\"{{results.persons.length}}\">\r\n        <view class=\"section-head\">\r\n          <text class=\"section-title\">人物</text>\r\n          <text class=\"section-count\">{{results.persons.length}} 位</text>\r\n        </view>\r\n        <view class=\"result-card\">\r\n          <view\r\n            wx:for=\"{{results.persons}}\"\r\n            wx:key=\"id\"\r\n            class=\"row\"\r\n            data-type=\"person\"\r\n            data-id=\"{{item.id}}\"\r\n            bindtap=\"onRowTap\"\r\n          >\r\n            <view class=\"row-main\">\r\n              <text class=\"row-title\">{{item.title}}</text>\r\n              <text class=\"row-sub {{item.modern ? 'sub-modern' : ''}}\">{{item.sub}}</text>\r\n            </view>\r\n            <text class=\"row-arrow\">›</text>\r\n          </view>\r\n        </view>\r\n      </block>\r\n\r\n      <block wx:if=\"{{results.events.length}}\">\r\n        <view class=\"section-head\">\r\n          <text class=\"section-title\">史事</text>\r\n          <text class=\"section-count\">{{results.events.length}} 条</text>\r\n        </view>\r\n        <view class=\"result-card\">\r\n          <view\r\n            wx:for=\"{{results.events}}\"\r\n            wx:key=\"id\"\r\n            class=\"row\"\r\n            data-type=\"event\"\r\n            data-id=\"{{item.id}}\"\r\n            bindtap=\"onRowTap\"\r\n          >\r\n            <view class=\"row-main\">\r\n              <text class=\"row-title\">{{item.title}}</text>\r\n              <text class=\"row-sub {{item.modern ? 'sub-modern' : ''}}\">{{item.sub}}</text>\r\n            </view>\r\n            <text class=\"row-arrow\">›</text>\r\n          </view>\r\n        </view>\r\n      </block>\r\n\r\n      <block wx:if=\"{{results.panels.length}}\">\r\n        <view class=\"section-head\">\r\n          <text class=\"section-title\">朝代与专题</text>\r\n          <text class=\"section-count\">{{results.panels.length}} 个</text>\r\n        </view>\r\n        <view class=\"result-card\">\r\n          <view\r\n            wx:for=\"{{results.panels}}\"\r\n            wx:key=\"key\"\r\n            class=\"row\"\r\n            data-type=\"panel\"\r\n            data-id=\"{{item.id}}\"\r\n            data-mode=\"{{item.mode}}\"\r\n            bindtap=\"onRowTap\"\r\n          >\r\n            <view class=\"row-main\">\r\n              <text class=\"row-title\">{{item.title}}</text>\r\n              <text class=\"row-sub {{item.modern ? 'sub-modern' : ''}}\">{{item.sub}}</text>\r\n            </view>\r\n            <text class=\"row-arrow\">›</text>\r\n          </view>\r\n        </view>\r\n      </block>\r\n\r\n      <view class=\"empty\" wx:if=\"{{empty}}\">\r\n        <text class=\"empty-line\">未找到\"{{keyword}}\"相关内容</text>\r\n        <text class=\"empty-sub\">换个说法试试，比如\"汉武帝\"\"北宋\"\"辛亥\"</text>\r\n      </view>\r\n    </block>\r\n\r\n  </view>\r\n</view>\r\n"; });
